{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "དྭགས་བརྒྱུད་སྤྱིའི་གསོལ་འདེབས་ལས།",
      "head": "ཞེན་ལོག་སྒོམ་གྱི་རྐང་པར་གསུངས་པ་བཞིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཞེན་ལོག་དང་པོར་གལ་ཆེ་བ་དང་།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཟས་ནོར་ཀུན་ལ་ཆགས་ཞེན་མེད་པ་དང་། ། ཚེ་འདིའི་གདོས་ཐག་ཆོད་པའི་སྒོམ་ཆེན་ལ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཐུན་བཞི་བླ་མའི་རྣམ་འབྱོར་ལས་ཀྱང་།",
      "head": "ངེས་པར་འཆི་བ་སྙིང་ནས་དྲན་པ་དང་། ། མོས་གུས་རྣལ་མ་རྒྱུད་ལ་སྐྱེ་བ་ནས། ། ཞེན་ལོག་མཐའ་རུ་ཕྱིན་པའི་་་་་་་་་་་་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བཟང་སྤྱོད་སྨོན་ལམ་ལས།",
      "head": "ནམ་མཁའི་མཐར་ཐུག་གྱུར་པ་ཇི་ཙམ་པར། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱལ་སྲས་ཞི་བ་ལྷས་ཀྱང་།",
      "head": "ཇི་སྲིད་ནམ་མཁའ་གནས་པ་དང་། ། འགྲོ་བ་ཇི་སྲིད་གནས་གྱུར་པ། ། དེ་སྲིད་བདག་ནི་གནས་གྱུར་ནས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་བཙུན་མི་ལ་རས་པས།",
      "head": "མ་འོངས་གང་ཟག་ཐམས་ཅད་པ། ། གལ་ཏེ་སྒོམ་པ་ནུས་སྲིད་ན། །",
      "tail": ""
    }
  ]
}
